// 1. Récupération des données
const item = $input.item.json;
const image = $input.item.binary.data;

// 2. Extraction du SKU
const folderName = item.folderName || "";
const skuMatch = folderName.match(/EKS\d+/);
const extractedSku = skuMatch ? skuMatch[0] : "SKU-INCONNU";

// 3. Récupération de Magento
const magentoItems = $('GET_MAGENTO_PRODUCTS').all();
const product = magentoItems.find(p => p.json.sku === extractedSku);

// Préparation des variables par défaut
let brand = "specialized";
let model = "modele-inconnu";
let suffix = extractedSku.slice(-4);
let millesime = "2026";
let errorMsg = null;

const slugify = (str) => {
    return str.toLowerCase()
              .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
              .replace(/[^a-z0-9]/g, '-')
              .replace(/-+/g, '-')
              .replace(/^-|-$/g, '');
};

if (product) {
    brand = slugify(product.json.ekstere_brand || "marque");
    model = slugify(product.json.ekstere_model || "modele");
    millesime = slugify(product.json.ekstere_year || "2026");
} else {
    errorMsg = "SKU non trouvé dans Magento";
}

// FIX de l'index : n8n utilise $input.item.index dans ce mode
const photoIndex = ($input.item.index || 0) + 1;

const extension = (item.fileName || "image.jpg").split('.').pop();
const finalFileName = `ekstere-${brand}-${model}-${suffix}-${photoIndex}.${extension}`;

// On renvoie TOUJOURS sku_extracted
return {
  json: {
    ...item,
    sku_extracted: extractedSku, // Maintenant il sera toujours là
    brand: product ? product.json.ekstere_brand : null,
    model: product ? product.json.ekstere_model : null,
    millesime: product ? product.json.ekstere_year : null,
    newFileName: finalFileName,
    error: errorMsg
  },
  binary: {
    data: image,
    fileName: finalFileName 
  }
};














